import React, { useState, useEffect, useRef } from 'react';
import './Aibody.css';
import axios from 'axios';
import SpeechRecognition, { useSpeechRecognition } from 'react-speech-recognition';

const Aibody = () => {
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [inputText, setInputText] = useState("");
    const { transcript, listening, resetTranscript } = useSpeechRecognition();
    const textareaRef = useRef(null);

    useEffect(() => {
        const savedChatHistory = JSON.parse(localStorage.getItem('chatHistory'));
        if (savedChatHistory) setMessages(savedChatHistory);
    }, []);

    useEffect(() => {
        if (messages.length > 0) {
            localStorage.setItem('chatHistory', JSON.stringify(messages));
        }
    }, [messages]);

    if (!SpeechRecognition.browserSupportsSpeechRecognition()) {
        return <div>Your browser does not support speech recognition. Please use a modern browser.</div>;
    }

    const handleStartListening = () => {
        if (!listening) SpeechRecognition.startListening({ continuous: true });
    };

    const handleStopListening = async () => {
        if (listening) {
            SpeechRecognition.stopListening();
            const combinedInput = inputText || transcript;
            if (!combinedInput.trim()) {
                alert("Please say or type something before sending.");
                return;
            } else {
                await fetchApiResponse(combinedInput);
            }
            resetTranscript();
        }
    };

    const fetchApiResponse = async (input) => {
        setLoading(true);
        try {
            const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/v1/search/QueryAnything`, {
                input,
                chatHistory: messages
            }, {
                headers: { 'Content-Type': 'application/json' }
            });

            if (response.data && response.data.chatHistory) {
                setMessages(response.data.chatHistory);
            } else {
                setMessages((prevMessages) => [
                    ...prevMessages,
                    { role: 'user', content: input },
                    { role: 'assistant', content: 'Unexpected response format. Please try again.' }
                ]);
            }
        } catch (error) {
            console.error('Error fetching response from API:', error);
            setMessages((prevMessages) => [
                ...prevMessages,
                { role: 'user', content: input },
                { role: 'assistant', content: 'Error fetching response. Please try again.' }
            ]);
        } finally {
            setLoading(false);
            setInputText("");
            resetTranscript();
        }
    };

    const handleTextSubmit = async (e) => {
        e.preventDefault();
        const combinedInput = inputText || transcript;
        if (combinedInput.trim()) {
            await fetchApiResponse(combinedInput);
        } else {
            alert("Please enter or say something before submitting.");
        }
        resetTranscript();
    };

    const handleResetResponses = () => {
        setMessages([]);
        resetTranscript();
        setInputText("");
        localStorage.removeItem('chatHistory');
    };

    const autoResize = () => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = "auto"; // Reset height to auto to shrink if necessary
            textarea.style.height = `${Math.min(textarea.scrollHeight, 80)}px`; // Set max height to 80px (5rem)
        }
    };

    return (
        <div className="Contain">
            <div className="nav">
                <div className="nav2">
                    <h1>Chat AI</h1>
                </div>
                <div className="nav1">
                    <img src="voice1.png" alt="" />
                </div>
            </div>

            <div className="butn" style={{ marginBottom: "20px" }}>
                <button
                    className="startbutn"
                    onClick={handleStartListening}
                    disabled={listening || inputText.trim().length > 0}
                >
                    Start Listening
                </button>
                <button
                    className="stopbutn"
                    onClick={handleStopListening}
                    disabled={!listening}
                >
                    Stop Listening
                </button>
                <button
                    className="resetbutn"
                    onClick={handleResetResponses}
                    style={{ padding: "10px", fontSize: "16px" }}
                >
                    Reset Responses
                </button>
                {listening && <p>Listening... Please speak now.</p>}
            </div>

            {loading ? (
                <p>Loading response...</p>
            ) : (
                <div className="txtresponse">
                    <textarea
                        value={messages
                            .map(
                                (msg, index) =>
                                    `Role: ${msg.role}:\nMessage: ${msg.content}\n\n`
                            )
                            .join("")}
                        rows="10"
                        cols="50"
                        readOnly
                        placeholder="AI responses will appear here..."
                    />
                </div>
            )}
           
            <form onSubmit={handleTextSubmit}>
                <div className="respcontainer">
                    <div className="txtrequest">
                        <textarea
                            ref={textareaRef}
                            value={inputText || transcript}
                            onChange={(e) => {
                                setInputText(e.target.value);
                                autoResize();
                            }}
                            rows="1"
                            placeholder="Type your Query.."
                            disabled={listening}
                            style={{ overflowY: "hidden" }}
                        />
                    </div>
                    <div className="buttnn">
                        <button
                            type="submit"
                            className="startbutn1"
                            disabled={!inputText.trim()}
                        >
                            <i className="fa-solid fa-play"></i>
                        </button>
                    </div>
                </div>
            </form>
        </div>
    );
};

export default Aibody;
